<?php
require_once __DIR__.'/../includes/admin.php';require_role(['super_admin','admin','editor']);$pdo=db();
if(is_post()){verify_csrf();$a=$_POST['action']??'';try{if($a==='save'){$id=(int)($_POST['id']??0);$d=[trim($_POST['title_en']??''),trim($_POST['title_am']??''),trim($_POST['description_en']??''),trim($_POST['description_am']??''),$_POST['event_date']??'',$_POST['start_time']??null,$_POST['end_time']??null,trim($_POST['location']??''),trim($_POST['image']??''),(int)isset($_POST['registration_enabled']),($_POST['status']??'draft')==='published'?'published':'draft'];if($id){$st=$pdo->prepare('UPDATE events SET title_en=?,title_am=?,description_en=?,description_am=?,event_date=?,start_time=?,end_time=?,location=?,image=?,registration_enabled=?,status=? WHERE id=?');$st->execute([...$d,$id]);log_admin("Updated event #$id");}else{$st=$pdo->prepare('INSERT INTO events(title_en,title_am,description_en,description_am,event_date,start_time,end_time,location,image,registration_enabled,status) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$st->execute($d);log_admin('Created event');}flash('admin_success','Event saved.');}if($a==='delete'){$id=(int)$_POST['id'];$pdo->prepare('DELETE FROM events WHERE id=?')->execute([$id]);log_admin("Deleted event #$id");flash('admin_success','Event deleted.');}}catch(Throwable $e){flash('admin_error','Event error: '.$e->getMessage());}redirect('admin/events.php');}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM events WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$rows=$pdo->query('SELECT * FROM events ORDER BY event_date DESC,created_at DESC')->fetchAll();admin_page('Events','events','Create, edit, publish and delete fellowship events.');admin_flash();
?><div class="admin-panel"><h2><?= $edit?'Edit Event':'Add Event' ?></h2><form class="admin-form" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??0))?>"><div class="admin-form-grid"><label>Title (English)<input name="title_en" required value="<?=e($edit['title_en']??'')?>"></label><label>Title (Amharic)<input name="title_am" value="<?=e($edit['title_am']??'')?>"></label></div><div class="admin-form-grid"><label>Description (English)<textarea name="description_en" rows="4"><?=e($edit['description_en']??'')?></textarea></label><label>Description (Amharic)<textarea name="description_am" rows="4"><?=e($edit['description_am']??'')?></textarea></label></div><div class="admin-form-grid three"><label>Date<input type="date" name="event_date" required value="<?=e($edit['event_date']??'')?>"></label><label>Start time<input type="time" name="start_time" value="<?=e($edit['start_time']??'')?>"></label><label>End time<input type="time" name="end_time" value="<?=e($edit['end_time']??'')?>"></label></div><div class="admin-form-grid"><label>Location<input name="location" value="<?=e($edit['location']??'')?>"></label><label>Image path<input name="image" placeholder="assets/images/events/event.jpg" value="<?=e($edit['image']??'')?>"></label></div><label><input type="checkbox" name="registration_enabled" <?=!empty($edit['registration_enabled'])?'checked':''?>> Enable registration button</label><label>Status<select name="status"><option value="draft" <?=($edit['status']??'')==='draft'?'selected':''?>>Draft</option><option value="published" <?=($edit['status']??'')==='published'?'selected':''?>>Published</option></select></label><div class="admin-actions"><button class="btn primary">Save Event</button><?php if($edit): ?><a class="btn outline" href="events.php">Cancel</a><?php endif;?></div></form></div><div class="admin-panel"><h2>Event List</h2><div class="admin-table-wrap"><table class="admin-table"><tr><th>Event</th><th>Date</th><th>Location</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['title_en'])?></td><td><?=e($r['event_date'])?></td><td><?=e($r['location'])?></td><td><span class="status <?=e($r['status'])?>"><?=e($r['status'])?></span></td><td><a class="btn small outline" href="events.php?edit=<?=$r['id']?>">Edit</a> <form style="display:inline" method="post" onsubmit="return confirm('Delete event?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small" style="background:var(--red);color:#fff">Delete</button></form></td></tr><?php endforeach;?></table></div></div><?php admin_end(); ?>
